import{_ as t,o as i,c as a,a3 as r,j as e,a as s}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/schueler/menueband-menueband.png",o="/bilder/schueler/menueband-bearbeitung.png",f=JSON.parse('{"title":"Das Menüband für Schülerdaten verwenden","description":"","frontmatter":{"title":"Das Menüband für Schülerdaten verwenden","source_pageid":378,"source_revision":5237},"headers":[],"relativePath":"schild3/schueler/menueband-schueler.md","filePath":"schild3/schueler/menueband-schueler.md"}'),u={name:"schild3/schueler/menueband-schueler.md"};function l(c,n,h,g,p,m){return i(),a("div",null,[...n[0]||(n[0]=[r('<h1 id="das-menuband-fur-schulerdaten-verwenden" tabindex="-1">Das Menüband für Schülerdaten verwenden <a class="header-anchor" href="#das-menuband-fur-schulerdaten-verwenden" aria-label="Permalink to &quot;Das Menüband für Schülerdaten verwenden&quot;">​</a></h1><p>Bearbeiten Sie Schülerdatensätze und nutzen Sie die Funktionen zum Suchen, Filtern und Sortieren. Bestätigen Sie Änderungen mit Übernehmen und beachten Sie die Hinweise vor Löschaktionen.</p><p><a href="/bilder/schueler/menueband-menueband.png"><img src="'+d+'" alt="Menüband" loading="lazy"></a></p><p><em>Menüband</em></p><p>Im Reiter <strong>Schüler</strong> gibt es die Möglichkeit die Daten zu bearbeiten, verschiedene Aktionen zu starten und die Daten zu filtern.</p><p>Der erste Bereich im Menüband sind die Funktionen der Gruppe <em>&quot;Bearbeitung&quot;</em>.</p><p>An dieser Stelle ist es möglich neue Datensätze anzulegen (&quot;<strong>Einfügen</strong>&quot;), bestehende Daten zu <strong>aktualisieren</strong>, zu <strong>bearbeiten</strong> oder auch zu <strong>löschen</strong>.</p><p><a href="/bilder/schueler/menueband-bearbeitung.png"><img src="'+o+'" alt="Die Gruppe Bearbeitung kann je nach Version leicht anders aussehen." loading="lazy"></a></p><p><em>Die Gruppe Bearbeitung kann je nach Version leicht anders aussehen.</em></p><p>Bei der Bearbeitung von Daten ist es immer wichtig die Änderungen mit dem Button &quot;<strong>Übernehmen</strong>&quot; zu bestätigen, um die Einträge in die Datenbank zu übertragen.</p><p>Sollen bestehende Einträge gelöscht werden, erscheinen mehrere Warnhinweise, die noch bestätigt werden müssen.</p>',11),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),s("Achtung")]),e("p",null,"Warnhinweise immer genau lesen!")],-1),r('<p>Mit dem Button &quot;<strong>Abbrechen</strong>&quot; ist es möglich die Eingabe von Daten abzubrechen.</p><p>Der zweite Bereich im Menüband ist <em>&quot;Suchen, filtern und sortieren&quot;</em>.</p><ul><li><strong>Suchen</strong> öffnet die Suchmaske. Dort suchen Sie nach einer bestimmten Schülerin oder einem bestimmten Schüler.</li><li><strong>Filter auf markierte Schüler</strong> beschränkt die Auswahl auf die markierten Personen. Für diese Gruppe können Sie anschließend Gruppenprozesse ausführen oder gespeicherte Daten ändern.</li><li><strong>Sortierreihenfolge ändern</strong> legt die Reihenfolge der angezeigten Schülerinnen und Schüler fest.</li><li>Die Schaltfläche &quot;<strong>Standard-Auswahl</strong>&quot; stellt die als Standard gewählte Reihenfolge wieder her.</li></ul><p>Der Bereich &quot;Andere&quot; enthält die Funktion &quot;<strong>Wiedervorlage anzeigen</strong>&quot;. Damit wird die Maske zur Verwaltung der Wiedervorlagen aufgerufen.</p><p>Im Bereich <strong>Drucken</strong> stehen <strong>Drucken</strong> und <strong>Reports</strong> zur Verfügung. Damit geben Sie Dokumente für einzelne Personen oder Listen für die aktuell gefilterte Schülergruppe aus.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Men%C3%BCband_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5237.</p>',7)])])}const _=t(u,[["render",l]]);export{f as __pageData,_ as default};
